import java.util.*;

class Solution {
  public int validSubarraySize(int[] nums, int threshold) {
    int n = nums.length;
    int[] st = new int[n + 1];
    int top = 0;
    for (int i = 0; i <= n; i++) {
      int cur = i == n ? 0 : nums[i];
      while (top > 0 && nums[st[top - 1]] > cur) {
        int h = nums[st[--top]], len = top == 0 ? i : i - st[top - 1] - 1;
        if ((long) h * len > threshold) return len;
      }
      st[top++] = i;
    }
    return -1;
  }
}
